targets.expr:
(
  sum by (pod, location, data_type) (
    rate(internal_cache_cell_access_hit_bytes_total{app_kubernetes_io_instance=~"$instance", app_kubernetes_io_name="$app_name", namespace="$namespace", app_kubernetes_io_component=~"querynode|standalone"}[1m])
  )
  /
  (
    sum by (pod, location, data_type) (
      rate(internal_cache_cell_access_hit_bytes_total{app_kubernetes_io_instance=~"$instance", app_kubernetes_io_name="$app_name", namespace="$namespace", app_kubernetes_io_component=~"querynode|standalone"}[1m])
    )
    +
    sum by (pod, location, data_type) (
      rate(internal_cache_cell_access_miss_bytes_total{app_kubernetes_io_instance=~"$instance", app_kubernetes_io_name="$app_name", namespace="$namespace", app_kubernetes_io_component=~"querynode|standalone"}[1m])
    )
  )
) * 100 and on(pod, location, data_type) (
  sum by (pod, location, data_type) (
    rate(internal_cache_cell_access_hit_bytes_total{app_kubernetes_io_instance=~"$instance", app_kubernetes_io_name="$app_name", namespace="$namespace", app_kubernetes_io_component=~"querynode|standalone"}[1m])
  )
  +
  sum by (pod, location, data_type) (
    rate(internal_cache_cell_access_miss_bytes_total{app_kubernetes_io_instance=~"$instance", app_kubernetes_io_name="$app_name", namespace="$namespace", app_kubernetes_io_component=~"querynode|standalone"}[1m])
  )
) > 0

(
  sum by (pod, location, data_type) (
    rate(internal_cache_cell_access_miss_bytes_total{app_kubernetes_io_instance=~"$instance", app_kubernetes_io_name="$app_name", namespace="$namespace", app_kubernetes_io_component=~"querynode|standalone"}[1m])
  )
  /
  (
    sum by (pod, location, data_type) (
